import React from 'react';
import StatCard from '../components/ui/StatCard';
import AnalyticsCharts from '../components/dashboard/AnalyticsCharts';

export default function Analytics() {
  return <><div className="page-heading"><div><div className="eyebrow">INSIGHTS & IMPACT</div><h1>Environmental analytics</h1><p>Track trends and measure your region’s impact.</p></div><button className="select-like">Last 30 days⌄</button></div><div className="stat-grid analytics-stats"><StatCard title="Reports received" value="128" change="↑ 14.2%" note="vs. previous period" icon="▤" tone="green"/><StatCard title="Resolution rate" value="78%" change="↑ 6.4%" note="vs. previous period" icon="✓" tone="mint"/><StatCard title="Avg. response time" value="4.2h" change="↓ 18%" note="faster than last month" icon="◷" tone="blue"/><StatCard title="Citizen reports" value="94%" change="↑ 3.1%" note="of total submissions" icon="♙" tone="amber"/></div><AnalyticsCharts/><section className="panel response-panel analytic-response"><div className="panel-heading"><div><h2>Response performance</h2><p>Average time to first officer action</p></div></div><div className="response-content"><div className="ring"><div><b>4.2h</b><small>average time</small></div></div><div className="response-stats"><div><span>Under 2 hours</span><b>38%</b></div><div><span>Under 8 hours</span><b>82%</b></div><div><span>Over 24 hours</span><b>6%</b></div></div></div></section></>;
}
